			WPA_LOGW("%s: send timeout\r\n", __func__);
		} else {
			ret = node->cb.result;
			if (ret < 0)
				WPA_LOGW("%s: send failed\r\n", __func__);
		}
		rtos_lock_mutex(&l2_packet->l2_mutex);
		dl_list_for_each_safe(item, n, &l2_packet->head_list, struct l2_packet_node, list)
		{
			if(item->cb.l2_tag == node->cb.l2_tag)
			{
				dl_list_del(&item->list);
				rtos_deinit_semaphore(&(item->cb.sema));
				break;
			}
		}
		rtos_unlock_mutex(&l2_packet->l2_mutex);
		if(node) {
			os_free(node);
			node = 0;
		}
	}
