int rw_msg_send(const void *msg_params, int reqcfm, uint16_t reqid, void *cfm)
{
	int ret;
	struct ke_msg *msg = ke_param2msg(msg_params);
	MSG_SND_NODE_PTR tx_msg = 0;
	int err = BK_OK;

	GLOBAL_INT_DECLARATION();

	if (g_wifi_enable_flag == false) {
		ke_msg_free(msg);
		RWNX_LOGI("%s Wi-Fi is NOT enable, please enable Wi-Fi first\n", __FUNCTION__);
		err = BK_ERR_WIFI_NOT_INIT;
		goto failed_or_timeout;
	}

	// Need wait cfm from full mac
	if (reqcfm) {
		tx_msg = os_malloc(sizeof(MSG_SND_NODE_ST));
		if (!tx_msg)
			return BK_ERR_NO_MEM;

		tx_msg->msg = msg;
		tx_msg->reqid = reqid;
		tx_msg->cfm = cfm;

		ret = rtos_init_semaphore(&tx_msg->semaphore, 1);
		BK_ASSERT(0 == ret); /* ASSERT VERIFIED */

		GLOBAL_INT_DISABLE();
		co_list_push_back(&rw_msg_tx_head, &tx_msg->hdr);
		GLOBAL_INT_RESTORE();

	}

	///wakeup mac but do not config pwr bit
	///in the future, if the msg doesn't need to wakeup mac, can use bmsg_software_para_ioctl_sender()
	if ((ME_TRAFFIC_IND_REQ == msg->id) ||
		(ME_GET_BSS_INFO_REQ == msg->id) ||
		(MM_SET_LISTEN_INTERVAL_REQ == msg->id) ||
		(MM_SET_BCN_LOSS_INT_REQ == msg->id) ||
		(MM_SET_PSDEBUG_INTERVAL_REQ == msg->id) ||
		(ME_STA_ARP_UPDATE_IND == msg->id) ||
		(MM_SET_ARP_TX_RATE_REQ == msg->id)) {
		ret = bmsg_hardware_para_ioctl_sender((void *)msg_params);
	} else {
		ret = bmsg_ioctl_sender((void *)msg_params);
	}
	if (kNoErr != ret) {
		RWNX_LOGD("%s failed send %d\n", __FUNCTION__, msg->id);
		os_free((void *)msg_params);
		err = RWNX_ERR_IOCTL_SEND;
		goto failed_or_timeout;
	} else if (reqcfm) {
		ret = rtos_get_semaphore(&tx_msg->semaphore, 5 * MICROSECONDS);
			if (0 != ret) {
			/* Timeout already maps to RWNX_ERR_TIMEOUT below; a hard panic
			 * here also wedges the ke task mid-request during bring-up
			 * (observed once with the functional clock finally running and
			 * hal_machw_reset's park loop stalling), so downgrade to the
			 * error return the surrounding code already handles. */
			RWNX_LOGE("%s timeout for %d\n", __FUNCTION__, reqid);
				err = RWNX_ERR_TIMEOUT;

			goto failed_or_timeout;
		}

		ret = rtos_deinit_semaphore(&tx_msg->semaphore);
		BK_ASSERT(0 == ret); /* ASSERT VERIFIED */

		os_free(tx_msg);
	}

	return BK_OK;

failed_or_timeout:
	if (tx_msg) {
		/* The confirmation worker and timeout path share ownership through
		 * rw_msg_tx_head.  Do not free a node RX already extracted until RX
		 * has completed its locked CFM copy and semaphore post. */
		GLOBAL_INT_DISABLE();
		if (co_list_find(&rw_msg_tx_head, &tx_msg->hdr))
			co_list_extract(&rw_msg_tx_head, &tx_msg->hdr);
		GLOBAL_INT_RESTORE();

		ret = rtos_deinit_semaphore(&tx_msg->semaphore);
		BK_ASSERT(0 == ret); /* ASSERT VERIFIED */
		os_free(tx_msg);
	}

	return err;
}

